<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Filter;

use Throwable;

use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetFilter;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAccesible
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(private readonly Context $context)
  {
  }
  public function __invoke(TemplateAssetRestrictFilterToVisibility $event): TemplateAssetRestrictFilterToVisibility
  {
    $this->logDebug("Check TenantAccesible Template asset");
    $span = $this->startSpan("Check TenantAccesible Template asset");
    try {
      $userContext = $this->context->getIdentity();
      if (!$userContext->hasAnyRole('platform:*')) {
              $tenantTenantAccesible = $userContext->tenant;
      if (!$userContext->anonymous && null !== $tenantTenantAccesible) {
        $event->templateAssetFilter = $event->templateAssetFilter->withTenantTenantAccesible($tenantTenantAccesible);
      } else {
        throw new UnauthorizedException('The claim tenant is required');
      }
      }
      return $event;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
